parameters.jsCode:
// Guards against sending a WhatsApp request with a template/campaign that
// hasn't been set up yet for this attempt number. Pabbly's "API Campaign"
// broadcast type requires BOTH a templateName and a campaignName per call
// (confirmed against a real Pabbly curl example) -- each pre-created
// campaign in Pabbly's dashboard has its own template attached, so attempts
// 2-4 each need their own campaign created there before whatsapp_campaign_2..4
// can be filled in (only "review", attempt 1, exists as of 2026-08-24).
// Without these checks, a null value would be sent straight to Pabbly and
// fail there instead of here, with a less useful error.
// Also guards review_request_link, since Pabbly's "link" field would be sent
// as null otherwise -- currently true for every business, none have a real link set yet.
const results = [];
for (const item of $input.all()) {
  const attemptNumber = item.json.attempt_count + 1;
  if (!item.json.whatsapp_template) {
    throw new Error(
      `No whatsapp_template_${attemptNumber} set for business "${item.json.business_name}" ` +
      `(customer_id: ${item.json.customer_id}) — write and Meta-approve this template before attempt ${attemptNumber} can send.`
    );
  }
  if (!item.json.whatsapp_campaign) {
    throw new Error(
      `No whatsapp_campaign_${attemptNumber} set for business "${item.json.business_name}" ` +
      `(customer_id: ${item.json.customer_id}) — create a Pabbly campaign for attempt ${attemptNumber} and set this column to its Campaign Name.`
    );
  }
  if (!item.json.review_request_link) {
    throw new Error(
      `No review_request_link set for business "${item.json.business_name}" ` +
      `(customer_id: ${item.json.customer_id}) — set the business's Google review URL before sending.`
    );
  }
  results.push(item);
}
return results;

// Guards against sending an email with a missing subject/intro for this
// attempt number, so a null value fails here with a clear message instead
// of either erroring inside Gmail's node or (worse) silently sending an
// email with "undefined" text in the subject/body.
// Also guards review_request_link, since the email's "Leave a Review" button
// would otherwise render as href="" -- currently true for every business,
// none have a real link set yet.
const results = [];
for (const item of $input.all()) {
  const attemptNumber = item.json.attempt_count + 1;
  if (!item.json.email_subject || !item.json.email_intro) {
    throw new Error(
      `Missing email_subject_${attemptNumber}/email_intro_${attemptNumber} for business "${item.json.business_name}" ` +
      `(customer_id: ${item.json.customer_id}) — set both before attempt ${attemptNumber} can send.`
    );
  }
  if (!item.json.review_request_link) {
    throw new Error(
      `No review_request_link set for business "${item.json.business_name}" ` +
      `(customer_id: ${item.json.customer_id}) — set the business's Google review URL before sending.`
    );
  }
  results.push(item);
}
return results;

